"""Apply only account-log compatibility changes to the pinned deployed Center image."""
import hashlib
import json
from pathlib import Path

PATCHES = [['/app/center/src/jbm_cluster_py/platform/center/modules/governance/application/compatibility_service.py', [['                rows = [\n                    {\n                        **row,\n                        "accountType": row.get("loginType"),\n                        "loginIp": row.get("ip"),\n                        "loginStatus": int(row.get("status") or 0) == 1,\n                        "loginAgent": row.get("userAgent"),\n                        "browser": row.get("userAgent"),\n                    }\n                    for row in rows\n                ]\n', '                rows = [\n                    {\n                        **row,\n                        "loginType": row.get("loginType") or row.get("accountType"),\n                        "accountType": row.get("loginType") or row.get("accountType"),\n                        "loginIp": row.get("ip") or row.get("loginIp"),\n                        "loginStatus": int(row.get("status", row.get("loginStatus")) or 0) == 1,\n                        "userAgent": row.get("userAgent") or row.get("loginAgent"),\n                        "loginAgent": row.get("userAgent") or row.get("loginAgent"),\n                        "browser": row.get("userAgent") or row.get("loginAgent"),\n                    }\n                    for row in rows\n                ]\n']]], ['/app/center/src/jbm_cluster_py/platform/center/modules/governance/infrastructure/crud_store.py', [['        params: dict[str, Any] = {}\n        for key, value in (filters or {}).items():\n            column = _snake(key)\n            if value in (None, "") or column not in columns or column in {"page", "page_size"}:\n                continue\n            if isinstance(value, str) and column not in {pk, "status", "app_id", "parent_id", "user_id", "role_id", "policy_id"}:\n', '        params: dict[str, Any] = {}\n        for key, value in (filters or {}).items():\n            column = _snake(key)\n            if resource == "accountLogs" and column not in columns:\n                column = {"login_type": "account_type", "ip": "login_ip", "status": "login_status",\n                          "user_agent": "login_agent"}.get(column, column)\n            if value in (None, "") or column not in columns or column in {"page", "page_size"}:\n                continue\n            if isinstance(value, str) and column not in {pk, "status", "app_id", "parent_id", "user_id", "role_id", "policy_id"}:\n'], ['        where = " WHERE " + " AND ".join(clauses) if clauses else ""\n        page = max(int(page), 1)\n        size = min(max(int(size), 1), 100)\n        async with self.engine.connect() as conn:\n            total = int((await conn.execute(text(f"SELECT COUNT(*) FROM {table}{where}"), params)).scalar() or 0)\n            rows = (\n                await conn.execute(\n                    text(f"SELECT * FROM {table}{where} ORDER BY {pk} LIMIT :limit OFFSET :offset"),\n                    {**params, "limit": size, "offset": (page - 1) * size},\n                )\n            ).mappings().all()\n', '        where = " WHERE " + " AND ".join(clauses) if clauses else ""\n        page = max(int(page), 1)\n        size = min(max(int(size), 1), 100)\n        order = f"login_time DESC, {pk} DESC" if resource == "accountLogs" and "login_time" in columns else pk\n        async with self.engine.connect() as conn:\n            total = int((await conn.execute(text(f"SELECT COUNT(*) FROM {table}{where}"), params)).scalar() or 0)\n            rows = (\n                await conn.execute(\n                    text(f"SELECT * FROM {table}{where} ORDER BY {order} LIMIT :limit OFFSET :offset"),\n                    {**params, "limit": size, "offset": (page - 1) * size},\n                )\n            ).mappings().all()\n']]]]

def apply(root=Path('/')):
    hashes = {}
    for filename, replacements in PATCHES:
        path = root / filename.lstrip('/')
        content = path.read_text(encoding='utf-8')
        for before, after in replacements:
            assert content.count(before) == 1, f'Unexpected Center base: {filename}'
            content = content.replace(before, after, 1)
        path.write_text(content, encoding='utf-8')
        compile(content, filename, 'exec')
        hashes[filename] = hashlib.sha256(content.encode()).hexdigest()
    return hashes

if __name__ == '__main__':
    print(json.dumps(apply(), sort_keys=True))
